from helpers import T
def f(cat, q, a, pages=None): return dict(category=cat, question=T(q), answer=T(a), pages=pages, is_published=True)
FAQS = [
    f("device", "Does applying the sensor hurt?", "<p>Most people describe it as a tap rather than a prick. The applicator places a flexible filament 5.5 mm long and half a millimetre wide under the skin in one spring-loaded motion; the guide needle retracts immediately. The back of the upper arm has few nerve endings, which is why it is the recommended site.</p>"),
    f("device", "How long does one sensor last?", "<p>15 days. The app counts down and reminds you the day before. After 15 days the sensor stops measuring and you apply a new one — the applicator always comes with the sensor already inside.</p>"),
    f("device", "Can I shower, swim or exercise with it?", "<p>Yes. The sensor and the patch are rated IP58: 30 minutes at a depth of 1.5 metres. Showers, pools and sweaty workouts are fine; pat the patch dry afterwards. Avoid saunas above +45 °C and long soaks in very hot water.</p>"),
    f("device", "Do I need to calibrate it with finger pricks?", "<p>No. Flystat is factory-calibrated and has no user calibration function. There are no test strips, codes or numbers to enter. Your doctor may still ask you to confirm a reading with a blood glucose meter in specific situations — for example when symptoms do not match the number.</p>"),
    f("device", "How soon do I get the first reading?", "<p>60 minutes after applying. During the warm-up the sensor settles in the tissue; the app shows a timer. The 15-day period starts after warm-up.</p>"),
    f("device", "Where on the body do I wear it?", "<p>On the back of the upper arm — the site the device is designed and tested for. Rotate between arms with each new sensor and avoid scars, moles and areas where clothing straps rub.</p>"),
    f("device", "What happens if the sensor falls off early?", "<p>Press the patch edges firmly for ten seconds after applying and keep the area dry for the first hour; most sensors stay on for the full 15 days. If one does come off, it cannot be reapplied — log it in the app and contact support; a replacement policy will be published together with the sales terms after certification.</p>"),
    f("device", "How far can the phone be from the sensor?", "<p>Up to 10 metres with Bluetooth Low Energy, less through walls. If the phone is out of range the sensor keeps measuring and stores the full 15 days; the app fills the gap when you reconnect.</p>"),
    f("device", "Is the sensor affected by paracetamol, vitamin C or other medicines?", "<p>Some substances can interfere with glucose sensors. The list of known interferences for Flystat will be published in the user manual once clinical evaluation is complete. Until then: if a reading does not match how you feel, confirm with a blood glucose meter.</p>"),
    f("device", "What is in the box?", "<p>An applicator with the sensor already inside, a round fixing patch 49 mm across, an alcohol wipe and a quick guide. The box is 54 × 54 × 91 mm. Nothing to assemble.</p>"),
    f("app", "Which phones work with the Flystat app?", "<p>iPhones and Android phones from roughly the last five years with Bluetooth Low Energy and NFC for activation. The exact list of supported models will be published with the app release.</p>"),
    f("app", "Can my family or doctor see my readings live?", "<p>Not in the first release. Live sharing with family members and clinicians is planned for a later version after certification, and we do not promise a date. Today you can export a report as a PDF in two taps and send it to anyone you choose.</p>"),
    f("app", "mmol/L or mg/dL?", "<p>Both. The app follows your country's convention by default and you can switch at any time. The website does the same — look for the unit switch next to any glucose figure.</p>"),
    f("app", "What alerts are there?", "<p>Low, high and rapid-change alerts with thresholds you set, a quiet mode for the night, and an urgent-low alarm that always sounds. Alert settings are something to agree with your clinician.</p>"),
    f("app", "Where is my data stored?", "<p>On your phone and, if you enable backup, in an encrypted cloud account tied to your login. You decide what to export and to whom. We do not sell health data and we do not show advertising.</p>"),
    f("app", "Does the app replace my doctor?", "<p>No. Flystat is a monitoring device. Treatment decisions — doses, diet, activity — should be made with your healthcare professional, and readings that do not match your symptoms should be confirmed with a blood glucose meter.</p>"),
    f("purchase", "When and where can I buy Flystat?", "<p>Flystat is not on sale yet. We are going through CE marking and expect to complete it by the end of 2027; sales start after that, country by country through distributors. Join the waiting list and we will write to you when it reaches your country.</p>"),
    f("purchase", "How much will it cost?", "<p>We do not publish prices before certification, and we will not take pre-payments. Pricing will be set with local distributors and announced per country.</p>"),
    f("purchase", "Will insurance or national health systems cover it?", "<p>That depends on each country's reimbursement rules and happens after local registration. Our distributors will handle reimbursement applications where they exist.</p>"),
    f("purchase", "Is Flystat certified?", "<p>Not yet. The CE conformity assessment under the EU Medical Device Regulation is in progress; completion is planned for the end of 2027. We do not use CE, FDA or ISO marks on this website until they are granted.</p>"),
    f("partners", "Which regions are you looking for distributors in?", "<p>Our priority is the Middle East, Europe and Africa, followed by Asia and the Americas. Countries with a signed partner are shown on the map on the partners page; everything else is open.</p>", ["partners"]),
    f("partners", "What does a memorandum of understanding commit me to?", "<p>Intent, region and timeline — not purchase volumes. The memorandum lets both sides prepare the market before certification; supply agreements with volumes and prices follow CE marking.</p>", ["partners"]),
    f("partners", "Can I get exclusivity?", "<p>Yes, for partners who commit to a launch plan: country or regional exclusivity for a defined period, with milestones. We discuss the terms on the first call.</p>", ["partners"]),
    f("partners", "What materials and training do you provide?", "<p>Presentation, specification sheet, press kit, renders and video, website content in nine languages, product and application training for your teams, and a single contact in our regulatory team for local registration.</p>", ["partners"]),
    f("partners", "What about local registration after CE?", "<p>We supply the technical documentation and support the registration in each country; the distributor leads the local process. Timelines differ by regulator and we plan them together.</p>", ["partners"]),
    f("clinicians", "What does the sensor measure?", "<p>Glucose in the interstitial fluid, with an enzymatic filament 5.5 mm long. Interstitial values lag blood glucose by several minutes, which is why trend arrows matter as much as the number.</p>", ["clinicians"]),
    f("clinicians", "What is the accuracy (MARD)?", "<p>We will publish MARD and consensus error grid results when our clinical performance studies are complete, as part of CE marking. We do not present laboratory figures as clinical accuracy.</p>", ["clinicians"]),
    f("clinicians", "Can patients export data in a standard format?", "<p>The app exports an AGP-style PDF report and a CSV of readings and events. A clinic web view with patient consent is planned for a later release.</p>", ["clinicians"]),
    f("clinicians", "Can my clinic take part in studies or pilots?", "<p>Clinical studies are planned for 2027 as part of the conformity assessment; pilots follow certification. Write to clinical@flycgm.com and we will keep you informed.</p>", ["clinicians"]),
    f("support", "I found a problem on the website. Where do I report it?", "<p>Use the support form and choose “website error”. The page address, your browser and screen size are attached automatically; add a screenshot if you can. You will receive a ticket number by email.</p>", ["support", "manual"]),
    f("support", "How do I remove the sensor?", "<p>Peel the patch slowly from the edge, folding it back on itself; warm water or baby oil at the edge helps. The filament comes out with the sensor. Dispose of the sensor as described in the manual — it contains a battery.</p>", ["support", "manual"]),
    f("support", "How do I dispose of a used sensor and applicator?", "<p>The applicator is household plastic waste after the guide needle has retracted. The sensor contains a lithium cell and electronics and should go to electronic or battery waste collection according to local rules; details are in the manual.</p>", ["support", "manual"]),
]
